import com.badlogic.gdx.math.Vector2;
import com.badlogic.gdx.math.Interpolation;
import java.util.ArrayList;
import java.util.List;
import java.awt.Color;
import java.awt.Graphics;
import javax.swing.JFrame;
import javax.swing.JPanel;

public class PhysicsUtils {
    public static Vector2 velocityToPosition(Body body, Vector2 targetPosition, float maxSpeed, float deltaTime, float stepFrequency, float interpolationAlpha) {
        Vector2 currentPosition = body.getPosition();
        Vector2 targetDirection = targetPosition.cpy().sub(currentPosition);
        float distanceToTarget = targetDirection.len();

        float maxDistancePerFrame = maxSpeed * deltaTime * stepFrequency;
        Vector2 desiredVelocity = targetDirection.scl(maxSpeed / distanceToTarget);

        if (distanceToTarget < maxDistancePerFrame) {
            return targetDirection;
        } else {
            Vector2 currentVelocity = body.getLinearVelocity();
            return currentVelocity.lerp(desiredVelocity, interpolationAlpha);
        }
    }
}

public class Body {
    private Vector2 position;
    private Vector2 linearVelocity;

    public Body(Vector2 position, Vector2 linearVelocity) {
        this.position = position;
        this.linearVelocity = linearVelocity;
    }

    public Vector2 getPosition() {
        return position;
    }

    public Vector2 getLinearVelocity() {
        return linearVelocity;
    }

    public void setLinearVelocity(Vector2 velocity) {
        linearVelocity = velocity;
    }

    public void updatePosition(float deltaTime) {
        position.add(linearVelocity.cpy().scl(deltaTime));
    }
}

public class Simulation {
    public static void main(String[] args) {
        float deltaTime = 1 / 60f;  // Example delta time
        float maxSpeed = 100.0f;  // Example maximum speed in meters per second
        Vector2 targetPosition = new Vector2(10, 10);  // Example target position

        Vector2 initialPosition = new Vector2(0, 0);
        Vector2 initialVelocity = new Vector2(0, 0);

        Body bodySmooth = new Body(initialPosition, initialVelocity);
        Body bodyInterpolated = new Body(initialPosition, initialVelocity);

        List<Vector2> positionsSmooth = new ArrayList<>();
        List<Vector2> velocitiesSmooth = new ArrayList<>();

        List<Vector2> positionsInterpolated = new ArrayList<>();
        List<Vector2> velocitiesInterpolated = new ArrayList<>();

        int framesSmooth = simulateMovement("smooth", bodySmooth, targetPosition, maxSpeed, deltaTime, 60, positionsSmooth, velocitiesSmooth);
        int framesInterpolated = simulateMovement("interpolated", bodyInterpolated, targetPosition, maxSpeed, deltaTime, 60, positionsInterpolated, velocitiesInterpolated, 0.1f);

        System.out.println("Frames to reach target (smooth method): " + framesSmooth);
        System.out.println("Frames to reach target (interpolated method): " + framesInterpolated);

        // Plotting the results using a simple Java Swing application
        JFrame frame = new JFrame("Movement Simulation");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(800, 600);
        frame.add(new PlotPanel(positionsSmooth, positionsInterpolated, velocitiesSmooth, velocitiesInterpolated));
        frame.setVisible(true);
    }

    public static int simulateMovement(String method, Body body, Vector2 targetPosition, float maxSpeed, float deltaTime, float stepFrequency, List<Vector2> positions, List<Vector2> velocities, float interpolationAlpha) {
        int frames = 0;

        while (true) {
            Vector2 velocity = method.equals("smooth")
                ? PhysicsUtils.smoothVelocityToPosition(body, targetPosition, maxSpeed, deltaTime, stepFrequency)
                : PhysicsUtils.velocityToPosition(body, targetPosition, maxSpeed, deltaTime, stepFrequency, interpolationAlpha);

            body.setLinearVelocity(velocity);
            body.updatePosition(deltaTime);
            frames++;

            positions.add(body.getPosition().cpy());
            velocities.add(body.getLinearVelocity().cpy());

            if (body.getPosition().dst(targetPosition) < 0.01f) {  // Consider the body has reached the target
                break;
            }
        }

        return frames;
    }

    public static Vector2 smoothVelocityToPosition(Body body, Vector2 targetPosition, float maxSpeed, float deltaTime, float stepFrequency) {
        Vector2 currentPosition = body.getPosition();
        Vector2 targetDirection = targetPosition.cpy().sub(currentPosition);
        float distanceToTarget = targetDirection.len();

        float maxDistancePerFrame = maxSpeed * deltaTime * stepFrequency;
        Vector2 velocity = targetDirection.scl(deltaTime * maxSpeed * stepFrequency);

        return velocity;
    }
}

public class PlotPanel extends JPanel {
    private List<Vector2> positionsSmooth;
    private List<Vector2> positionsInterpolated;
    private List<Vector2> velocitiesSmooth;
    private List<Vector2> velocitiesInterpolated;

    public PlotPanel(List<Vector2> positionsSmooth, List<Vector2> positionsInterpolated, List<Vector2> velocitiesSmooth, List<Vector2> velocitiesInterpolated) {
        this.positionsSmooth = positionsSmooth;
        this.positionsInterpolated = positionsInterpolated;
        this.velocitiesSmooth = velocitiesSmooth;
        this.velocitiesInterpolated = velocitiesInterpolated;
    }

    @Override
