        super.paintComponent(g);
        g.setColor(Color.BLACK);
        g.drawLine(0, 300, 800, 300);  // X-axis
        g.drawLine(400, 0, 400, 600);  // Y-axis

        g.setColor(Color.RED);
        g.fillOval((int) (positionsSmooth.get(0).x * 40 + 400) - 5, (int) (positionsSmooth.get(0).y * -40 + 300) - 5, 10, 10);  // Initial position
        g.fillOval((int) (positionsSmooth.get(positionsSmooth.size() - 1).x * 40 + 400) - 5, (int) (positionsSmooth.get(positionsSmooth.size() - 1).y * -40 + 300) - 5, 10, 10);  // Target position

        g.setColor(Color.BLUE);
        for (Vector2 pos : positionsSmooth) {
            g.fillOval((int) (pos.x * 40 + 400) - 2, (int) (pos.y * -40 + 300) - 2, 4, 4);
        }

        g.setColor(Color.GREEN);
        for (Vector2 pos : positionsInterpolated) {
