public class Vista2023SceneController : MonoBehaviour
{
    public Transform Player;
    public float RenderDistance = 100f;
    public float ChunkSize = 50f;

    private Dictionary<Vector2Int, TerrainChunk> chunks = new Dictionary<Vector2Int, TerrainChunk>();
    private Queue<Vector2Int> loadQueue = new Queue<Vector2Int>();
    private Queue<Vector2Int> unloadQueue = new Queue<Vector2Int>();

    void Start()
    {
        StartCoroutine(LoadChunks());
        StartCoroutine(UnloadChunks());
    }

    void Update()
    {
        Vector3 playerPosition = Player.position;
        HashSet<Vector2Int> visibleChunks = GetVisibleChunks(playerPosition);

        // Queue chunks for loading and unloading
        foreach (Vector2Int chunk in visibleChunks)
        {
            if (!chunks.ContainsKey(chunk))
            {
                loadQueue.Enqueue(chunk);
            }
        }

        List<Vector2Int> keysToUnload = new List<Vector2Int>(chunks.Keys);
        foreach (Vector2Int chunk in keysToUnload)
        {
            if (!visibleChunks.Contains(chunk))
            {
                unloadQueue.Enqueue(chunk);
            }
        }
    }

    private HashSet<Vector2Int> GetVisibleChunks(Vector3 playerPosition)
    {
        HashSet<Vector2Int> visibleChunks = new HashSet<Vector2Int>();
        int minX = Mathf.FloorToInt((playerPosition.x - RenderDistance) / ChunkSize);
        int maxX = Mathf.FloorToInt((playerPosition.x + RenderDistance) / ChunkSize);
        int minZ = Mathf.FloorToInt((playerPosition.z - RenderDistance) / ChunkSize);
        int maxZ = Mathf.FloorToInt((playerPosition.z + RenderDistance) / ChunkSize);

        for (int x = minX; x <= maxX; x++)
        {
            for (int z = minZ; z <= maxZ; z++)
            {
                visibleChunks.Add(new Vector2Int(x, z));
            }
        }

        return visibleChunks;
    }

    private IEnumerator LoadChunks()
    {
        while (true)
        {
            if (loadQueue.Count > 0)
            {
                Vector2Int chunk = loadQueue.Dequeue();
                if (!chunks.ContainsKey(chunk))
                {
                    TerrainChunk terrainChunk = new TerrainChunk(chunk, ChunkSize);
                    terrainChunk.GenerateTerrain();
                    terrainChunk.Render();
                    chunks[chunk] = terrainChunk;
                }
            }
            yield return null; // Yield to allow other operations
        }
    }

    private IEnumerator UnloadChunks()
    {
        while (true)
        {
            if (unloadQueue.Count > 0)
            {
                Vector2Int chunk = unloadQueue.Dequeue();
                if (chunks.ContainsKey(chunk))
                {
                    chunks[chunk].Unload();
                    chunks.Remove(chunk);
                }
            }
            yield return null; // Yield to allow other operations
        }
    }
}
